fn main() {
    let source = r#"Feature: Imported transactions
  Scenario: Preserve imported values
    Given a payment
      | amount | 42 |
      """
      invoice 42
      """
    Then a separate step
"#;
    let feature = cucumber::gherkin::Feature::parse(source, Default::default())
        .expect("table-before-docstring must parse through cucumber's public API");
    let steps = &feature.scenarios[0].steps;
    assert_eq!(steps.len(), 2);
    assert_eq!(steps[0].table.as_ref().unwrap().rows, vec![vec!["amount", "42"]]);
    assert_eq!(steps[0].docstring.as_deref(), Some("\ninvoice 42\n"));
    assert_eq!(steps[1].value, "a separate step");
    assert!(steps[1].table.is_none());
    assert!(steps[1].docstring.is_none());
    println!("portable consumer observed exact table, doc string and following step");
}

